import { cn } from "@/lib/utils"

type Medium = "web" | "slide"
type SlideStatementCopy = { statement: string; support?: string }

export function SlideStatement({ copy, medium = "web" }: { copy: SlideStatementCopy; medium?: Medium }) {
  const slide = medium === "slide"
  return (
    <section data-slot="slide-statement" data-medium={medium} className={cn("flex flex-col justify-center gap-8 bg-background text-foreground", slide ? "aspect-video w-full overflow-hidden px-24 py-20" : "px-6 py-20 md:px-12")}>
      <p className={cn("max-w-5xl font-heading font-semibold tracking-tight", slide ? "text-7xl" : "text-3xl md:text-4xl")}>{copy.statement}</p>
      {copy.support ? <p className={cn("max-w-3xl text-muted-foreground", slide ? "text-3xl" : "text-lg")}>{copy.support}</p> : null}
    </section>
  )
}
